[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">

  <!-- Primary Meta Tags -->
  <title>WellStream Platform — Integrated Energy Data Management</title>
  <meta name="title" content="WellStream Platform — Integrated Energy Data Management">
  <meta name="description" content="WellStream delivers integrated SaaS solutions for energy operators to manage well data, production, and land assets. Streamline operations and enhance decision-making with real-time data integration. Request a demo today.">

  <!-- Canonical URL -->
