  <meta property="og:image" content="https://www.wellstream.com/og-image.jpg">

  <!-- Twitter -->
  <meta property="twitter:card" content="summary_large_image">
  <meta property="twitter:url" content="https://www.wellstream.com/">
  <meta property="twitter:title" content="WellStream Platform — Integrated Energy Data Management">
  <meta property="twitter:description" content="WellStream delivers integrated SaaS solutions for energy operators to manage well data, production, and land assets.">
  <meta property="twitter:image" content="https://www.wellstream.com/og-image.jpg">

  <!-- Favicons -->
  <link rel="icon" type="image/svg+xml" href="data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'><rect width='32' height='32' rx='6' fill='%2315295A'/><text x='16' y='22' font-size='18' fill='white' text-anchor='middle' font-family='sans-serif'>W</text></svg>">

  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap" rel="stylesheet">

  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    :root {
      --bg-deep: #0D1B2A;
      --bg-dark: #1B2838;
      --navy: #15295A;
      --accent: #00B4D8;
      --accent-deep: #0077B6;
      --green: #6CC24A;
      --gray: #3C424B;
      --text: #E8ECF1;
      --text-muted: #8B95A5;
      --text-dim: #5A6577;
      --white: #FFFFFF;
      --border: rgba(255,255,255,0.08);
      --radius: 8px;
      --radius-lg: 12px;
      --shadow: 0 4px 24px rgba(0,0,0,0.3);
    }
    html { scroll-behavior: smooth; }
    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
      background: var(--bg-deep);
      color: var(--text);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
    }
    .container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }
    .container-narrow { max-width: 900px; margin: 0 auto; padding: 0 24px; }

    /* Navigation */
    .nav { position: fixed; top: 0; left: 0; right: 0; z-index: 1000; background: rgba(13,27,42,0.95); backdrop-filter: blur(12px); border-bottom: 1px solid var(--border); transition: background 0.3s; }
    .nav.scrolled { background: rgba(13,27,42,0.98); }
    .nav-inner { display: flex; align-items: center; justify-content: space-between; height: 72px; max-width: 1200px; margin: 0 auto; padding: 0 24px; }
    .nav-logo { display: flex; align-items: center; gap: 10px; text-decoration: none; font-weight: 700; font-size: 1.3rem; color: var(--white); }
    .nav-logo-icon { width: 36px; height: 36px; background: var(--navy); border-radius: 8px; display: flex; align-items: center; justify-content: center; font-weight: 800; font-size: 1.1rem; color: var(--white); }
    .nav-links { display: flex; align-items: center; gap: 28px; list-style: none; }
    .nav-links a { color: var(--text-muted); text-decoration: none; font-size: 0.9rem; font-weight: 500; transition: color 0.2s; }
    .nav-links a:hover { color: var(--white); }
    .nav-dropdown { position: relative; }
    .nav-dropdown-toggle { background: none; border: none; color: var(--text-muted); font-size: 0.9rem; font-weight: 500; cursor: pointer; display: flex; align-items: center; gap: 4px; font-family: inherit; transition: color 0.2s; }
    .nav-dropdown-toggle:hover { color: var(--white); }
    .nav-dropdown-toggle svg { width: 12px; height: 12px; transition: transform 0.2s; }
    .nav-dropdown.open .nav-dropdown-toggle svg { transform: rotate(180deg); }
    .nav-dropdown-menu { position: absolute; top: 100%; left: -16px; margin-top: 8px; background: var(--bg-dark); border: 1px solid var(--border); border-radius: var(--radius-lg); padding: 8px 0; min-width: 200px; opacity: 0; visibility: hidden; transform: translateY(-8px); transition: all 0.2s; box-shadow: var(--shadow); }
    .nav-dropdown.open .nav-dropdown-menu { opacity: 1; visibility: visible; transform: translateY(0); }
    .nav-dropdown-menu a { display: block; padding: 10px 20px; color: var(--text-muted); font-size: 0.88rem; transition: all 0.15s; }
    .nav-dropdown-menu a:hover { background: rgba(255,255,255,0.05); color: var(--white); }
    .nav-cta { display: inline-flex; align-items: center; gap: 8px; background: var(--accent); color: var(--white); padding: 10px 20px; border-radius: 6px; text-decoration: none; font-weight: 600; font-size: 0.88rem; transition: all 0.2s; }
    .nav-cta:hover { background: var(--accent-deep); transform: translateY(-1px); }
    .nav-mobile-toggle { display: none; background: none; border: none; cursor: pointer; padding: 4px; }
    .nav-mobile-toggle span { display: block; width: 24px; height: 2px; background: var(--white); margin: 5px 0; transition: all 0.3s; border-radius: 2px; }
    .nav-mobile-toggle.active span:nth-child(1) { transform: rotate(45deg) translate(5px,5px); }
    .nav-mobile-toggle.active span:nth-child(2) { opacity: 0; }
    .nav-mobile-toggle.active span:nth-child(3) { transform: rotate(-45deg) translate(5px,-5px); }

    /* Hero */
    .hero { padding: 160px 0 100px; position: relative; overflow: hidden; }
    .hero::before { content: ''; position: absolute; top: -50%; right: -20%; width: 600px; height: 600px; background: radial-gradient(circle, rgba(0,180,216,0.08) 0%, transparent 70%); }
    .hero::after { content: ''; position: absolute; bottom: -30%; left: -10%; width: 400px; height: 400px; background: radial-gradient(circle, rgba(21,41,90,0.3) 0%, transparent 70%); }
    .hero-inner { position: relative; z-index: 1; display: grid; grid-template-columns: 1fr 1fr; gap: 60px; align-items: center; }
    .hero-badge { display: inline-block; background: rgba(0,180,216,0.12); color: var(--accent); padding: 6px 14px; border-radius: 100px; font-size: 0.8rem; font-weight: 600; letter-spacing: 0.05em; margin-bottom: 20px; }
    .hero h1 { font-size: 3.2rem; font-weight: 800; line-height: 1.15; color: var(--white); margin-bottom: 20px; letter-spacing: -0.02em; }
    .hero h1 span { color: var(--accent); }
    .hero-subtitle { font-size: 1.1rem; color: var(--text-muted); margin-bottom: 36px; line-height: 1.7; max-width: 520px; }
    .hero-actions { display: flex; gap: 16px; flex-wrap: wrap; }
    .btn { display: inline-flex; align-items: center; gap: 8px; padding: 14px 28px; border-radius: 8px; font-weight: 600; font-size: 0.95rem; text-decoration: none; cursor: pointer; transition: all 0.2s; border: none; font-family: inherit; }
    .btn-primary { background: var(--accent); color: var(--white); }
    .btn-primary:hover { background: var(--accent-deep); transform: translateY(-2px); box-shadow: 0 8px 24px rgba(0,180,216,0.25); }
    .btn-outline { background: transparent; color: var(--white); border: 1.5px solid rgba(255,255,255,0.25); }
    .btn-outline:hover { border-color: var(--white); background: rgba(255,255,255,0.05); }
    .hero-visual { display: flex; align-items: center; justify-content: center; }
    .hero-diagram { width: 100%; max-width: 500px; }

    /* Ecosystem Diagram */
    .ecosystem-diagram { display: flex; flex-direction: column; gap: 16px; }
    .eco-pillar { background: var(--bg-dark); border: 1px solid var(--border); border-radius: var(--radius-lg); padding: 20px 24px; position: relative; transition: all 0.3s; }
    .eco-pillar:hover { border-color: var(--accent); transform: translateX(4px); }
    .eco-pillar::before { content: ''; position: absolute; left: 0; top: 20px; bottom: 20px; width: 3px; border-radius: 2px; }
    .eco-pillar.well::before { background: var(--accent); }
    .eco-pillar.prod::before { background: var(--green); }
    .eco-pillar.land::before { background: var(--accent-deep); }
    .eco-pillar-label { font-size: 0.7rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.1em; color: var(--text-dim); margin-bottom: 6px; }
    .eco-pillar h3 { font-size: 1.05rem; font-weight: 700; color: var(--white); }
    .eco-pillar p { font-size: 0.85rem; color: var(--text-muted); margin-top: 4px; }
    .eco-center { display: flex; align-items: center; justify-content: center; }
    .eco-hub { background: var(--navy); border: 2px solid var(--accent); border-radius: 50%; width: 80px; height: 80px; display: flex; align-items: center; justify-content: center; font-weight: 700; font-size: 0.85rem; color: var(--white); text-align: center; }
    .eco-connector { width: 2px; height: 20px; background: linear-gradient(to bottom, var(--accent), transparent); margin: 0 auto; }

    /* Sections */
    .section { padding: 100px 0; }
    .section-dark { background: var(--bg-dark); }
    .section-label { font-size: 0.75rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.12em; color: var(--accent); margin-bottom: 12px; }
    .section-title { font-size: 2.2rem; font-weight: 800; color: var(--white); margin-bottom: 16px; letter-spacing: -0.02em; line-height: 1.2; }
    .section-desc { font-size: 1.05rem; color: var(--text-muted); max-width: 640px; line-height: 1.7; margin-bottom: 48px; }

    /* Featured Banner */
    .featured-banner { background: linear-gradient(135deg, var(--navy) 0%, #0D1B2A 100%); border: 1px solid var(--border); border-radius: var(--radius-lg); padding: 36px 40px; display: flex; align-items: center; justify-content: space-between; gap: 24px; flex-wrap: wrap; }
    .featured-banner-info h3 { font-size: 0.7rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.1em; color: var(--accent); margin-bottom: 6px; }
    .featured-banner-info h2 { font-size: 1.5rem; font-weight: 800; color: var(--white); }
    .featured-banner-tag { display: inline-block; background: rgba(108,194,74,0.15); color: var(--green); padding: 4px 12px; border-radius: 100px; font-size: 0.78rem; font-weight: 600; margin-top: 8px; }
    .featured-banner .btn { flex-shrink: 0; }

    /* Use Cases Grid */
    .use-cases-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; }
    .use-case-card { background: var(--bg-dark); border: 1px solid var(--border); border-radius: var(--radius-lg); padding: 28px; cursor: pointer; transition: all 0.25s; text-decoration: none; color: inherit; display: block; }
    .use-case-card:hover { border-color: var(--accent); transform: translateY(-3px); box-shadow: var(--shadow); }
    .use-case-icon { width: 44px; height: 44px; border-radius: 10px; display: flex; align-items: center; justify-content: center; margin-bottom: 16px; font-size: 1.3rem; }
    .use-case-icon.drilling { background: rgba(0,180,216,0.12); color: var(--accent); }
    .use-case-icon.production { background: rgba(108,194,74,0.12); color: var(--green); }
    .use-case-icon.asset { background: rgba(0,119,182,0.12); color: var(--accent-deep); }
    .use-case-card h3 { font-size: 1rem; font-weight: 700; color: var(--white); margin-bottom: 8px; }
    .use-case-card p { font-size: 0.88rem; color: var(--text-muted); line-height: 1.5; }

    /* Industry Tabs */
    .tabs-nav { display: flex; gap: 4px; border-bottom: 1px solid var(--border); margin-bottom: 32px; overflow-x: auto; -webkit-overflow-scrolling: touch; }
    .tabs-nav button { background: none; border: none; color: var(--text-muted); padding: 12px 20px; font-size: 0.88rem; font-weight: 500; cursor: pointer; border-bottom: 2px solid transparent; transition: all 0.2s; white-space: nowrap; font-family: inherit; }
    .tabs-nav button:hover { color: var(--white); }
    .tabs-nav button.active { color: var(--accent); border-bottom-color: var(--accent); font-weight: 600; }
    .tab-panel { display: none; animation: fadeIn 0.3s ease; }
    .tab-panel.active { display: block; }
    @keyframes fadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }
    .tab-panel h3 { font-size: 1.3rem; font-weight: 700; color: var(--white); margin-bottom: 8px; }
    .tab-panel p { color: var(--text-muted); line-height: 1.7; margin-bottom: 16px; }
    .tab-panel ul { list-style: none; display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
    .tab-panel li { color: var(--text-muted); font-size: 0.9rem; padding: 8px 0; display: flex; align-items: center; gap: 8px; }
    .tab-panel li::before { content: ''; width: 6px; height: 6px; border-radius: 50%; background: var(--accent); flex-shrink: 0; }

    /* Company Culture */
    .culture-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 60px; align-items: center; }
    .culture-visual { background: var(--bg-dark); border: 1px solid var(--border); border-radius: var(--radius-lg); padding: 40px; text-align: center; min-height: 300px; display: flex; flex-direction: column; align-items: center; justify-content: center; }
    .culture-stat { font-size: 3.5rem; font-weight: 900; color: var(--accent); }
    .culture-stat-label { color: var(--text-muted); font-size: 0.9rem; margin-top: 4px; }
    .culture-text h2 { font-size: 2rem; font-weight: 800; color: var(--white); margin-bottom: 16px; }
    .culture-text p { color: var(--text-muted); line-height: 1.7; margin-bottom: 24px; }

    /* Renewables CTA */
    .renewables-cta { background: linear-gradient(135deg, #0A1628 0%, var(--navy) 50%, #0A3D1F 100%); border: 1px solid var(--border); border-radius: var(--radius-lg); padding: 48px; text-align: center; }
    .renewables-cta h2 { font-size: 1.8rem; font-weight: 800; color: var(--white); margin-bottom: 12px; }
    .renewables-cta p { color: var(--text-muted); max-width: 600px; margin: 0 auto 28px; line-height: 1.7; }

    /* Footer */
    .footer { background: var(--bg-dark); border-top: 1px solid var(--border); padding: 64px 0 32px; }
    .footer-grid { display: grid; grid-template-columns: 2fr 1fr 1fr 1fr 1fr; gap: 40px; }
    .footer-brand h3 { font-size: 1.1rem; font-weight: 700; color: var(--white); margin-bottom: 8px; }
    .footer-brand p { color: var(--text-muted); font-size: 0.85rem; line-height: 1.6; }
    .footer-col h4 { font-size: 0.75rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.08em; color: var(--text-dim); margin-bottom: 16px; }
    .footer-col ul { list-style: none; }
    .footer-col li { margin-bottom: 10px; }
    .footer-col a { color: var(--text-muted); text-decoration: none; font-size: 0.88rem; transition: color 0.2s; }
    .footer-col a:hover { color: var(--accent); }
    .footer-bottom { margin-top: 48px; padding-top: 24px; border-top: 1px solid var(--border); display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 16px; }
    .footer-bottom p { color: var(--text-dim); font-size: 0.82rem; }
    .footer-login a { color: var(--text-dim); font-size: 0.82rem; text-decoration: none; margin-left: 16px; transition: color 0.2s; }
    .footer-login a:hover { color: var(--accent); }

    /* Cookie Banner */
    .cookie-banner { position: fixed; bottom: 0; left: 0; right: 0; background: var(--bg-dark); border-top: 1px solid var(--border); padding: 20px 24px; z-index: 999; display: flex; align-items: center; justify-content: space-between; gap: 20px; flex-wrap: wrap; box-shadow: 0 -4px 24px rgba(0,0,0,0.4); }
    .cookie-banner p { color: var(--text-muted); font-size: 0.85rem; margin: 0; flex: 1; min-width: 240px; }
    .cookie-banner p a { color: var(--accent); text-decoration: underline; }
    .cookie-actions { display: flex; gap: 10px; }
    .btn-sm { padding: 8px 18px; font-size: 0.82rem; border-radius: 6px; }

    /* Page hero (subpages) */
    .page-hero { padding: 140px 0 80px; text-align: center; }
    .page-hero h1 { font-size: 2.8rem; font-weight: 800; color: var(--white); margin-bottom: 16px; letter-spacing: -0.02em; }
    .page-hero p { font-size: 1.1rem; color: var(--text-muted); max-width: 640px; margin: 0 auto; line-height: 1.7; }

    /* Platform Benefits */
    .benefits-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 20px; }
    .benefit-card { background: var(--bg-deep); border: 1px solid var(--border); border-radius: var(--radius-lg); padding: 28px; text-align: center; transition: all 0.25s; }
    .benefit-card:hover { border-color: var(--accent); transform: translateY(-2px); }
    .benefit-icon { width: 48px; height: 48px; border-radius: 12px; display: flex; align-items: center; justify-content: center; margin: 0 auto 16px; font-size: 1.4rem; }
    .benefit-icon.time { background: rgba(0,180,216,0.12); color: var(--accent); }
    .benefit-icon.resources { background: rgba(108,194,74,0.12); color: var(--green); }
    .benefit-icon.money { background: rgba(0,119,182,0.12); color: var(--accent-deep); }
    .benefit-icon.connected { background: rgba(108,194,74,0.12); color: var(--green); }
    .benefit-icon.secure { background: rgba(0,180,216,0.12); color: var(--accent); }
    .benefit-card h3 { font-size: 0.95rem; font-weight: 700; color: var(--white); margin-bottom: 8px; }
    .benefit-card p { font-size: 0.82rem; color: var(--text-muted); line-height: 1.5; }

    /* Stats Rings */
    .stats-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 30px; text-align: center; }
    .stat-ring { position: relative; width: 160px; height: 160px; margin: 0 auto 20px; }
    .stat-ring svg { transform: rotate(-90deg); }
    .stat-ring-bg { fill: none; stroke: var(--border); stroke-width: 8; }
    .stat-ring-fill { fill: none; stroke-width: 8; stroke-linecap: round; transition: stroke-dashoffset 1.5s ease; }
    .stat-ring-value { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; }
    .stat-ring-value span:first-child { font-size: 2rem; font-weight: 800; color: var(--white); }
    .stat-ring-value span:last-child { font-size: 0.78rem; color: var(--text-muted); }
    .stat-card p { color: var(--text-muted); font-size: 0.9rem; line-height: 1.5; }

    /* Timeline */
    .timeline { position: relative; padding-left: 40px; }
    .timeline::before { content: ''; position: absolute; left: 8px; top: 0; bottom: 0; width: 2px; background: var(--border); }
    .timeline-item { position: relative; margin-bottom: 40px; }
    .timeline-item:last-child { margin-bottom: 0; }
    .timeline-dot { position: absolute; left: -40px; top: 4px; width: 18px; height: 18px; border-radius: 50%; background: var(--accent); border: 3px solid var(--bg-deep); z-index: 1; }
    .timeline-item h3 { font-size: 1rem; font-weight: 700; color: var(--white); margin-bottom: 4px; }
    .timeline-item h3 span { font-size: 0.75rem; font-weight: 700; color: var(--accent); margin-right: 8px; }
    .timeline-item p { color: var(--text-muted); font-size: 0.9rem; margin-bottom: 12px; }
    .progress-bar { height: 4px; background: var(--bg-dark); border-radius: 2px; overflow: hidden; }
    .progress-fill { height: 100%; background: var(--accent); border-radius: 2px; transition: width 1.5s ease; }

    /* Accordion */
    .accordion { max-width: 800px; margin: 0 auto; }
    .accordion-item { border: 1px solid var(--border); border-radius: var(--radius-lg); margin-bottom: 12px; overflow: hidden; }
    .accordion-header { width: 100%; background: var(--bg-dark); border: none; color: var(--white); padding: 20px 24px; font-size: 1rem; font-weight: 600; cursor: pointer; display: flex; align-items: center; justify-content: space-between; font-family: inherit; transition: background 0.2s; text-align: left; }
    .accordion-header:hover { background: rgba(255,255,255,0.03); }
    .accordion-header svg { width: 18px; height: 18px; transition: transform 0.3s; flex-shrink: 0; }
    .accordion-item.open .accordion-header svg { transform: rotate(180deg); }
    .accordion-body { max-height: 0; overflow: hidden; transition: max-height 0.4s ease; }
    .accordion-body-inner { padding: 0 24px 20px; color: var(--text-muted); font-size: 0.92rem; line-height: 1.7; }

    /* Testimonial Carousel */
    .testimonial-carousel { position: relative; }
    .testimonial-slide { display: none; animation: fadeIn 0.3s ease; }
    .testimonial-slide.active { display: block; }
    .testimonial-card { background: var(--bg-dark); border: 1px solid var(--border); border-radius: var(--radius-lg); padding: 36px; text-align: center; max-width: 700px; margin: 0 auto; }
    .testimonial-card blockquote { font-size: 1.15rem; color: var(--text); font-style: italic; line-height: 1.6; margin-bottom: 16px; }
    .testimonial-card cite { font-size: 0.85rem; color: var(--text-dim); font-style: normal; }
    .carousel-dots { display: flex; justify-content: center; gap: 8px; margin-top: 24px; }
    .carousel-dot { width: 10px; height: 10px; border-radius: 50%; background: var(--border); border: none; cursor: pointer; transition: all 0.2s; padding: 0; }
    .carousel-dot.active { background: var(--accent); width: 28px; border-radius: 5px; }

    /* Data Lifecycle Diagram */
    .lifecycle-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; }
    .lifecycle-step { background: var(--bg-dark); border: 1px solid var(--border); border-radius: var(--radius-lg); padding: 24px; text-align: center; position: relative; }
    .lifecycle-step-num { width: 32px; height: 32px; border-radius: 50%; background: var(--accent); color: var(--white); display: flex; align-items: center; justify-content: center; font-weight: 700; font-size: 0.85rem; margin: 0 auto 12px; }
    .lifecycle-step h3 { font-size: 0.95rem; font-weight: 700; color: var(--white); margin-bottom: 6px; }
    .lifecycle-step p { font-size: 0.8rem; color: var(--text-muted); line-height: 1.4; }
    .lifecycle-arrow { position: absolute; top: 50%; right: -12px; color: var(--accent); font-size: 1.2rem; }

    /* Security Features */
