(function() {
  // Mobile nav toggle
  var toggle = document.getElementById('mobileToggle');
  var links = document.getElementById('navLinks');
  toggle.addEventListener('click', function() {
    toggle.classList.toggle('active');
    links.classList.toggle('open');
  });

  // Platform dropdown
  var dropdown = document.getElementById('platformDropdown');
  var dropdownToggle = document.getElementById('platformToggle');
  dropdownToggle.addEventListener('click', function(e) {
    e.preventDefault();
    dropdown.classList.toggle('open');
  });
  document.addEventListener('click', function(e) {
    if (!dropdown.contains(e.target)) dropdown.classList.remove('open');
  });

  // Nav scroll effect
  var nav = document.getElementById('nav');
  window.addEventListener('scroll', function() {
    nav.classList.toggle('scrolled', window.scrollY > 50);
  });

  // Industry tabs
  var tabButtons = document.querySelectorAll('#industryTabs button');
  var tabPanels = document.querySelectorAll('#industryTabContent .tab-panel');
  tabButtons.forEach(function(btn) {
    btn.addEventListener('click', function() {
      var tab = this.getAttribute('data-tab');
      tabButtons.forEach(function(b) { b.classList.remove('active'); });
      this.classList.add('active');
      tabPanels.forEach(function(p) {
        p.classList.toggle('active', p.getAttribute('data-tab') === tab);
      });
    });
  });

  // Cookie consent
  var cookieBanner = document.getElementById('cookieBanner');
  document.getElementById('cookieAccept').addEventListener('click', function() {
    localStorage.setItem('cookieConsent', 'accepted');
    cookieBanner.style.display = 'none';
  });
  document.getElementById('cookieDecline').addEventListener('click', function() {
    localStorage.setItem('cookieConsent', 'declined');
    cookieBanner.style.display = 'none';
  });
  if (localStorage.getItem('cookieConsent')) {
    cookieBanner.style.display = 'none';
  }
})();
