(function() {
  // Mobile nav
  var toggle = document.getElementById('mobileToggle');
  var links = document.getElementById('navLinks');
  toggle.addEventListener('click', function() {
    toggle.classList.toggle('active');
    links.classList.toggle('open');
  });

  // Platform dropdown
  var dropdown = document.getElementById('platformDropdown');
  var dropdownToggle = document.getElementById('platformToggle');
  dropdownToggle.addEventListener('click', function(e) {
    e.preventDefault();
    dropdown.classList.toggle('open');
  });
  document.addEventListener('click', function(e) {
    if (!dropdown.contains(e.target)) dropdown.classList.remove('open');
  });

  // Nav scroll
  var nav = document.getElementById('nav');
  window.addEventListener('scroll', function() {
    nav.classList.toggle('scrolled', window.scrollY > 50);
  });

  // Accordion
  var accHeaders = document.querySelectorAll('#accordion .accordion-header');
  accHeaders.forEach(function(header) {
    header.addEventListener('click', function() {
      var item = this.parentElement;
      var isOpen = item.classList.contains('open');
      // Close all
      document.querySelectorAll('#accordion .accordion-item').forEach(function(i) { i.classList.remove('open'); });
      // Open clicked (unless it was already open)
      if (!isOpen) {
        item.classList.add('open');
        item.querySelector('.accordion-body').style.maxHeight = item.querySelector('.accordion-body').scrollHeight + 'px';
      }
      // Reset max-height on others
      document.querySelectorAll('#accordion .accordion-item').forEach(function(i) {
        if (!i.classList.contains('open')) {
          i.querySelector('.accordion-body').style.maxHeight = '0';
        }
      });
    });
  });

  // Stats ring animation
  function animateRing(id, percentage) {
    var circle = document.getElementById(id);
    if (!circle) return;
    var circumference = 2 * Math.PI * 82;
    var offset = circumference - (percentage / 100) * circumference;
    setTimeout(function() { circle.style.strokeDashoffset = offset; }, 200);
  }

  function animateCount(el, target, suffix) {
    var current = 0;
    var duration = 1500;
    var step = Math.max(1, Math.floor(target / (duration / 30)));
    var interval = setInterval(function() {
      current += step;
      if (current >= target) { current = target; clearInterval(interval); }
      el.textContent = current + (suffix || '');
    }, 30);
  }

  // Intersection Observer for stats
  var statsObserved = false;
  var statsSection = document.getElementById('stats');
  function checkStats() {
    if (statsObserved) return;
    var rect = statsSection.getBoundingClientRect();
    if (rect.top < window.innerHeight - 100) {
      statsObserved = true;
      animateRing('ring1', 80);
      animateRing('ring2', 89);
      animateRing('ring3', 31);
      animateCount(document.getElementById('count1'), 80, '');
      animateCount(document.getElementById('count2'), 89, '%');
      animateCount(document.getElementById('count3'), 31, '%');
    }
  }
  window.addEventListener('scroll', checkStats);
  checkStats();

  // Timeline progress animation
  var timelineObserved = false;
  function animateTimeline() {
    if (timelineObserved) return;
    var timeline = document.querySelector('.timeline');
    if (!timeline) return;
    var rect = timeline.getBoundingClientRect();
    if (rect.top < window.innerHeight - 100) {
      timelineObserved = true;
      document.querySelectorAll('.progress-fill').forEach(function(bar) {
        setTimeout(function() { bar.style.width = bar.getAttribute('data-width') + '%'; }, 300);
      });
    }
  }
  window.addEventListener('scroll', animateTimeline);
  animateTimeline();

  // Testimonial carousel
  var slides = document.querySelectorAll('#testimonialCarousel .testimonial-slide');
  var dots = document.querySelectorAll('#carouselDots .carousel-dot');
  function goToSlide(index) {
    slides.forEach(function(s) { s.classList.remove('active'); });
    dots.forEach(function(d) { d.classList.remove('active'); });
    slides[index].classList.add('active');
    dots[index].classList.add('active');
  }
  dots.forEach(function(dot) {
    dot.addEventListener('click', function() {
      goToSlide(parseInt(this.getAttribute('data-index')));
    });
  });

  // About / Careers tabs
  var aboutButtons = document.querySelectorAll('#aboutTabsNav button');
  var aboutPanels = document.querySelectorAll('#aboutTabsContent .tab-panel');
  aboutButtons.forEach(function(btn) {
    btn.addEventListener('click', function() {
      var tab = this.getAttribute('data-tab');
      aboutButtons.forEach(function(b) { b.classList.remove('active'); });
      this.classList.add('active');
      aboutPanels.forEach(function(p) {
        p.classList.toggle('active', p.getAttribute('data-tab') === tab);
      });
    });
  });
})();
</script>

