<script>
(function() {
  // Mobile nav
  var toggle = document.getElementById('mobileToggle');
  var links = document.getElementById('navLinks');
  toggle.addEventListener('click', function() {
    toggle.classList.toggle('active');
    links.classList.toggle('open');
  });

  // Platform dropdown
  var dropdown = document.getElementById('platformDropdown');
  var dropdownToggle = document.getElementById('platformToggle');
  dropdownToggle.addEventListener('click', function(e) {
    e.preventDefault();
    dropdown.classList.toggle('open');
  });
  document.addEventListener('click', function(e) {
    if (!dropdown.contains(e.target)) dropdown.classList.remove('open');
  });

  // Nav scroll
  var nav = document.getElementById('nav');
  window.addEventListener('scroll', function() {
    nav.classList.toggle('scrolled', window.scrollY > 50);
  });

  // Demo form validation
  var form = document.getElementById('requestDemoForm');
  var formWrap = document.getElementById('demoForm');
  var successBox = document.getElementById('formSuccess');

  function validateEmail(email) {
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
  }

  function validateField(field) {
    var value = field.value.trim();
    var valid = true;

    if (field.hasAttribute('required') && !value) {
      valid = false;
    } else if (field.type === 'email' && value && !validateEmail(value)) {
      valid = false;
    }

    if (!valid) {
      field.classList.add('error');
    } else {
      field.classList.remove('error');
    }
    return valid;
  }

  // Live validation on blur
  form.querySelectorAll('input, select, textarea').forEach(function(field) {
    field.addEventListener('blur', function() {
      if (field.value.trim() || field.hasAttribute('required')) {
        validateField(field);
      }
    });
    field.addEventListener('input', function() {
      if (field.classList.contains('error')) {
        validateField(field);
      }
    });
  });

  form.addEventListener('submit', function(e) {
    e.preventDefault();
    var valid = true;
    var fields = form.querySelectorAll('input[required], select[required], textarea[required]');

    fields.forEach(function(field) {
      if (!validateField(field)) valid = false;
    });

    // Also validate email if provided
    var emailField = form.querySelector('input[name="email"]');
    if (emailField.value.trim() && !validateEmail(emailField.value.trim())) {
      emailField.classList.add('error');
      valid = false;
    }

    if (valid) {
      formWrap.style.display = 'none';
      successBox.style.display = 'block';
    } else {
      // Scroll to first error
      var firstError = form.querySelector('.error');
      if (firstError) firstError.focus();
    }
  });
})();
</script>

